// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 amount) public {
        // keep the domain wide but admissible: enough ETH to observe, small enough to avoid overflow issues
        amount = bound(amount, 2, 1 ether);

        // fund the contract with the fuzzed amount
        vm.deal(address(c), amount);

        // owner is the test contract (deployer of c)
        uint256 preContractBalance = address(c).balance;
        uint256 preOwnerBalance = address(this).balance;

        vm.prank(address(this));
        c.withdraw();

        // GENERAL RULE: after the Owner's withdraw(), the Owner has received the ENTIRE
        // contract balance (and thus address(c).balance == 0). The mutant sends only
        // balance/2, so for any amount >= 2 the owner gains less and a remainder stays.
        assertTrue(
            address(this).balance == preOwnerBalance + preContractBalance && address(c).balance == 0
        );
    }

    receive() external payable {}
}
